head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vSEG_CHG_TP_CD = "";
scwin.pLogType = "";
scwin.isNew = false;
scwin.notiId = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용
scwin.getPar, scwin.setPar;
scwin.fr_SecuGrpId;
scwin.vBzProcsNo;
scwin.vListProcsStatCd;
scwin.vAcptNo;
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.TR_JOB;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        inf_find.hide();
        $c.cm.PanelToGroupBox(panel_Item);
        $c.elw.fn_searchCode();
        await scwin.grdSearchCode();
        file_name.hide();
        const parentWin = $c.frame.path("../");
        if (parentWin.scwin.vScrenID === "ULDSTF05816.gfm") {
            scwin.isNew = true;
            // 신규작성

        } else {
            let dstObj = parentWin.dts_List_2;
            let row = dstObj.getFocusedRowIndex();
            scwin.vBzProcsNo = dstObj.getCellData(row, "BZ_PROCS_NO");
        }
        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성

        if (scwin.isNew) {
            // 신규작성중
            buttonSet.setInsertStatus();
            btn_Revwr.setBackgroundImage("../img/btn_study_d.gif");
            btn_Revwr.setDisabled(true);
            btn_Approve.setBackgroundImage("../img/btn_approval_d.gif");
            btn_Approve.setDisabled(true);
            btn_Dscl.setBackgroundImage("../img/btn_make_info_d.gif");
            btn_Dscl.setDisabled(true);
        } else {
            // 090720-팀원은 컴토만, 팀장은 승인만
            if (js_jobtitl === "03") {
                // 팀원'03'
                btn_Revwr.setBackgroundImage("../img/btn_study.gif");
                btn_Revwr.setDisabled(false);
                btn_Approve.setBackgroundImage("../img/btn_approval_d.gif");
                btn_Approve.setDisabled(true);
            } else {
                btn_Revwr.setBackgroundImage("../img/btn_study_d.gif");
                btn_Revwr.setDisabled(true);
                btn_Approve.setBackgroundImage("../img/btn_approval.gif");
                btn_Approve.setDisabled(false);
            }
            let dstObj = parentWin.dts_List_2;
            let row = dstObj.getFocusedRowIndex();
            scwin.vBzProcsNo = dstObj.getCellData(row, "BZ_PROCS_NO");
        }
        await scwin.readSync();
        if (scwin.isNew) {
            dts_Item.insertRow();
            rdo_SEG_CHG_TP_CD.setValue("01");
        }
        await scwin.fileSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05815.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Item_OnLoadError
 * @description dts_Item 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Item_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Item);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05815.dts_Item_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Item_OnLoadCompleted
 * @description dts_Item 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    try {
        let vCurDate = $c.ut.cGetToday("yyyymmdd");
        scwin.vSEG_CHG_TP_CD = dts_Item.getCellData(1, "SEG_CHG_TP_CD");
        const chgDd = edt_CHG_DD.getValue();
        if (chgDd > vCurDate) {
            buttonSet.setUpdateStatus();

            // 090720-팀원은 컴토만, 팀장은 승인만

            if (js_jobtitl === "03") {
                // 팀원'03'

                btn_Revwr.setBackgroundImage("../img/btn_study.gif");
                btn_Revwr.setDisabled(false);
                btn_Approve.setBackgroundImage("../img/btn_approval_d.gif");
                btn_Approve.setDisabled(true);
                if (edt_REVW_DDTM.getValue() !== "") {
                    btn_Revwr.setBackgroundImage("../img/btn_study_d.gif");
                    btn_Revwr.setDisabled(true);
                }
                if (edt_APPROV_DDTM.getValue() !== "") {
                    btn_Approve.setBackgroundImage("../img/btn_approval_d.gif");
                    btn_Approve.setDisabled(true);
                }
            } else {
                // 팀장 외

                btn_Revwr.setBackgroundImage("../img/btn_study_d.gif");
                btn_Revwr.setDisabled(true);
                btn_Approve.setBackgroundImage("../img/btn_approval.gif");
                btn_Approve.setDisabled(false);
                if (edt_REVW_DDTM.getValue() !== "") {
                    btn_Revwr.setBackgroundImage("../img/btn_study_d.gif");
                    btn_Revwr.setDisabled(true);
                }
                if (edt_APPROV_DDTM.getValue() !== "") {
                    btn_Approve.setBackgroundImage("../img/btn_approval_d.gif");
                    btn_Approve.setDisabled(true);
                }
            }
            // 승인이 되면 수정,삭제버튼 비활성화
            if (edt_APPROV_DDTM.getValue() !== "") {
                buttonSet.setErrorStatus(); // disable 시킨다.

            }
        } else if (chgDd !== "") {
            buttonSet.setErrorStatus(); // disable 시킨다.
            if (edt_REVW_DDTM.getValue() !== "") {
                btn_Revwr.setBackgroundImage("../img/btn_study_d.gif");
                btn_Revwr.setDisabled(true);
            }
            if (edt_APPROV_DDTM.getValue() !== "") {
                btn_Approve.setBackgroundImage("../img/btn_approval_d.gif");
                btn_Approve.setDisabled(true);
            }
        }
        if (edt_APPROV_DDTM.getValue() === "") {
            btn_Dscl.setBackgroundImage("../img/btn_make_info_d.gif");
            btn_Dscl.setDisabled(true);
        } else {
            btn_Dscl.setBackgroundImage("../img/btn_make_info.gif");
            btn_Dscl.setDisabled("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05815.dts_Item_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05815.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        if (scwin.isNew) {
            await $c.win.closePopup();
        } else {
            scwin.parentRefresh();
            if (buttonSet.status === "D") {
                // 삭제처리의 응답인 경우
                await $c.win.closePopup();
            } else {
                await scwin.readSync();
                await scwin.fileSync();
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05815.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Log_OnFail
 * @description Log On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Log_OnFail = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", scwin.TR_JOB));
        await $c.win.alert(trs_Log);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05815.trs_Log_OnFail" });
    }
};

/**
 * @method
 * @name trs_Log_OnSuccess
 * @description Log On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Log_OnSuccess = async function() {
    try {
        await $c.win.alert($c.stf.getMessageParam("MSG-0001", scwin.TR_JOB));
        scwin.parentRefresh();
        await scwin.readSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05815.trs_Log_OnSuccess" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05815.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name btn_Revwr_onclick
 * @description 「검토」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Revwr_onclick = async function() {
    try {
        await scwin.revwr();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05815.btn_Revwr_onclick" });
    }
};

/**
 * @method
 * @name btn_Approve_onclick
 * @description 「승인」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Approve_onclick = async function() {
    try {
        await scwin.approve();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05815.btn_Approve_onclick" });
    }
};

/**
 * @method
 * @name img_CHG_DD_onclick
 * @description img_CHG_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_CHG_DD_onclick = function() {
    try {
        popUpCalendar2(edt_CHG_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05815.img_CHG_DD_onclick" });
    }
};

/**
 * @method
 * @name grd_fielList_OnDblClick
 * @description grd_fielList 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_fielList_OnDblClick = function(row, colid) {
    try {
        if (colid === "ATTACH_FILE_NM" && dts_fileList.getRowStatus(dts_fileList.getRowPosition()) === 0) {
            const bzProcsNo = dts_fileList.getCellData(row, "BZ_PROCS_NO");
            const attachFileNo = dts_fileList.getCellData(row, "ATTACH_FILE_NO");
            $c.elw.fn_filedown(bzProcsNo, attachFileNo);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05815.grd_fielList_OnDblClick" });
    }
};

/**
 * @method
 * @name btn_lineadd_onclick
 * @description 「파일추가」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_lineadd_onclick = function() {
    try {
        dts_fileList.insertRow();
        inf_find.open();
        if (inf_find.getValue() !== "") {
            if (scwin.notiId === "input") {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                file_name.setValue(inf_find.getValue());
            } else {
                dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
                file_name.setValue(inf_find.getValue());
            }
        } else {
            dts_fileList.removeRow(dts_fileList.getRowPosition());
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05815.btn_lineadd_onclick" });
    }
};

/**
 * @method
 * @name btn_linedelete_onclick
 * @description 「파일삭제」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_linedelete_onclick = function() {
    try {
        const rtn = confirm('해당첨부파일을 삭제 하시겠습니까?');
        if (rtn === 1) {
            dts_fileList.removeRow(dts_fileList.getRowPosition());
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05815.btn_linedelete_onclick" });
    }
};

/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        scwin.getPar = scwin.getParIsur;
        scwin.setPar = scwin.setParIsur;
        $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05815.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name inf_find_OnClick
 * @description inf_find 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.inf_find_OnClick = function() {
    try {
        const filenm = file_name.getValue();
        if (scwin.notiId === "input") {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            file_name.setValue(inf_find.getValue());
        } else {
            dts_fileList.setCellData(dts_fileList.getRowPosition(), "fileInfo", inf_find.getValue());
            // dts_fileList.NameString(dts_fileList.rowposition, "ATTACH_SEQ") = dts_fileList.rowposition;
            file_name.setValue(inf_find.getValue());
        }
        if (inf_find.getValue() === "") {
            file_name.setValue(filenm);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05815.inf_find_OnClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    const arrCid = [{
        cid: "SEG_CHG_RSN_CD",
        cnm: "cmb_SEG_CHG_RSN_CD"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        // alert('[objCod]'+objCod);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name grdSearchCode
 * @description grd Search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grdSearchCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbdReason = "' ':"; // 초기값

    for (k = 1; k <= dts_Cod.getRowCount(); k++) {
        strCbdReason = strCbdReason + (strCbdReason === "" ? "" : ",") + dts_Cod.getCellData(k, "VALUE") + ":" + dts_Cod.getCellData(k, "TEXT");
    }
    $c.cm.setColumnProp(grd_fielList, 'SEG_CHG_APFM_FILE_TP_CD', 'Data', strCbdReason);
};

/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/SegmentChange.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name fileSync
 * @description file Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileSync = async function() {
    url += "&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_fileList",
        action : "/SegmentChange.do",
        ref : "",
        target : "dts_fileList=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name duplicateCheck
 * @description duplicate Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.duplicateCheck = async function() {
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&CHG_DD=" + edt_CHG_DD.getValue();
    const sbmOptions = {
        id : "sbm_dts_DUP_CHK",
        action : "/SegmentChange.do",
        ref : "",
        target : "dts_DUP_CHK=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    return dts_DUP_CHK.getCellData(1, "DUP_CHK");
};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @param {*} jobType jobType
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function(jobType) {
    dts_Item.setCellData(1, "JOB_TYPE", jobType);
    dts_Item.setCellData(1, "LIST_BZ_TP_CD", LIST_BZ_TP_CD_236);
    dts_Item.setCellData(1, "SPOT_ISU_TRD_MKT_TP_CD", "2");
    let vScrenProcTpCd;
    if (scwin.TR_JOB === "I") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === "U") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB === "D") {
        vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/SegmentChange.do",
        ref : "dts_Item,dts_fileList",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name trslog
 * @description trslog 처리
 * @param {*} logTyp logTyp
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trslog = async function(logTyp) {
    dts_Item.setCellData(1, "APPROV_TYPE", logTyp);
    dts_Item.setCellData(1, "REVWR_EMP_NO", js_emp_no);
    dts_Item.setCellData(1, "APPROV_EMP_NO", js_emp_no);
    dts_Item.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);

    // alert('[dts_Item]'+dts_Item.text);
    trs_Log.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Log",
        action : "/SegmentChange.do",
        ref : "dts_Item",
        target : "trs_Log=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    let vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISUR_NM.getValue() === "") {
        await $c.win.alert("[법인명] 항목을 선택하세요.");
        txb_ISUR_NM.focus();
        return false;
    }
    if (cmb_BFCHG_SEG_TP_CD.getValue() === "") {
        await $c.win.alert("[변경전] 항목을 선택하세요.");
        cmb_BFCHG_SEG_TP_CD.focus();
        return false;
    }
    if (cmb_SEG_TP_CD.getValue() === "") {
        await $c.win.alert("[변경후] 항목을 선택하세요.");
        cmb_SEG_TP_CD.focus();
        return false;
    }
    if (edt_CHG_DD.getValue() === "") {
        await $c.win.alert("[변경일]을 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if (vCurDate >= edt_CHG_DD.getValue()) {
        await $c.win.alert("[변경일]을 현재일이후로 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if (cmb_SEG_CHG_RSN_CD.getValue() === "") {
        await $c.win.alert("[변경사유]를 선택하세요.");
        cmb_SEG_CHG_RSN_CD.focus();
        return false;
    }
    for (let i = 1, j = dts_fileList.getRowCount(); i <= j; i++) {
        if (dts_fileList.getCellData(i, "SEG_CHG_APFM_FILE_TP_CD") === "") {
            await $c.win.alert("첨부서류 항목을 선택하세요.");
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (await scwin.duplicateCheck() === 'Y') {
            await $c.win.alert("[변경일]이 동일한 일자로 이미  입력되었습니다.");
            return;
        }
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        dts_Item.setCellData(1, "BZ_PROCS_NO", await $c.stf.getNewBzProcNo(dts_BzProcsNo));
        if (scwin.isNew) {
            dts_Item.setCellData(1, "IS_NEW", "Y");
        }
        await scwin.trs(TR_JOB_INSERT);
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.TR_JOB = 'U';
    if (await scwin.checkForm()) {
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        await scwin.trs(TR_JOB_UPDATE);
    }
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (edt_APPROV_DDTM.getValue() !== "") {
        await $c.win.alert("승인처리가 완료된 후 삭제 할 수 없습니다.");
        return;
    }
    scwin.TR_JOB = 'D';
    if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    await scwin.trs(TR_JOB_DELETE);
};

/**
 * @method
 * @name revwr
 * @description revwr 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.revwr = async function() {
    scwin.TR_JOB = '검토처리';
    scwin.pLogType = "1";
    let res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.TR_JOB));
    if (res) {
        await scwin.trslog('1');
    }
};

/**
 * @method
 * @name approve
 * @description approve 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.approve = async function() {
    if (edt_REVW_DDTM.getValue() === "") {
        await $c.win.alert("검토처리가 완료된 후 승인처리를 할 수 있습니다.");
        return;
    }
    scwin.TR_JOB = '승인처리';
    scwin.pLogType = "2";
    let res = window.confirm($c.stf.getMessageParam('MSG-A006', scwin.TR_JOB));
    if (res) {
        await scwin.trslog('2');
    }
};

